<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('operations','view');
global $conn;$tenantId=(int)getCurrentTenantId();$rows=[];$q=$conn->prepare("SELECT * FROM agent_sales WHERE tenant_id=? ORDER BY id DESC LIMIT 500");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$rows[]=$r;$q->close();}
$pageTitle='Agent Sales';require_once '../includes/header.php';?><div class="dashboard-card"><div class="page-header"><div><h2>Agent Sales</h2><p>Track agent sales, commissions and settlement status.</p></div></div><div class="table-responsive"><table><thead><tr><th>Agent</th><th>Product</th><th>Reference</th><th>Amount</th><th>Commission</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><?=e($x['agent_name'])?></td><td><?=e($x['product_type'])?></td><td><?=e($x['reference']??'—')?></td><td><?=e(formatMoney($x['amount']))?></td><td><?=e(formatMoney($x['commission']))?></td><td><?=e($x['status'])?></td><td><?=e($x['sold_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No agent sales recorded.</td></tr><?php endif;?></tbody></table></div></div><?php require_once '../includes/footer.php';?>